import ast, json, tempfile, unittest
from pathlib import Path
from grader import grade
BASE=Path(__file__).resolve().parent
MODULES=json.loads((BASE/'curriculum.json').read_text())
class HarnessTests(unittest.TestCase):
    def run_code(self,code,timeout=2):
        with tempfile.TemporaryDirectory() as folder:
            submission=Path(folder)/'starter.py';submission.write_text(code)
            return grade(MODULES[2],submission,timeout)
    def test_syllabus(self):
        self.assertEqual([m['week'] for m in MODULES],list(range(1,17)))
        self.assertEqual(len({m['function'] for m in MODULES}),16)
        for m in MODULES:
            self.assertTrue(m['requirements']);self.assertTrue(m['cases'])
            ast.parse('def '+m['function']+'(record):\n    raise NotImplementedError()\n')
    def test_week3_reference(self):
        result=self.run_code("def validate_task(r):\n    return isinstance(r,dict) and set(r)=={'id','title','status'} and all(isinstance(r[k],str) and bool(r[k].strip()) for k in ('id','title')) and r['status'] in ('open','completed')\n")
        self.assertEqual(result['passed'],4);self.assertIsNone(result['final_grade'])
    def test_incorrect_submission(self):
        result=self.run_code('def validate_task(r): return True\n')
        self.assertEqual(result['passed'],1)
    def test_import_failure(self):
        self.assertEqual(self.run_code('raise RuntimeError()\n')['failure'],'execution_failed')
    def test_timeout(self):
        self.assertEqual(self.run_code('while True: pass\n',0.2)['failure'],'timeout')
    def test_output_limit(self):
        self.assertEqual(self.run_code("print('x'*100000)\n")['failure'],'output_limit')
if __name__=='__main__': unittest.main()

const content=document.getElementById('content'),status=document.getElementById('status'),search=document.getElementById('search');
function element(tag,text){const node=document.createElement(tag);node.textContent=text;return node}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
fetch('curriculum.json').then(r=>{if(!r.ok)throw Error('Curriculum unavailable');return r.json()}).then(modules=>{function render(){content.replaceChildren();for(const m of modules.filter(m=>(m.week+' '+m.title+' '+m.requirements).toLowerCase().includes(search.value.toLowerCase()))){const section=element('section','');section.append(element('h2','Week '+m.week+': '+m.title),element('p',m.requirements));const starter='def '+m.function+'(record):\n    raise NotImplementedError("Implement week '+m.week+'")\n';const details=element('details','');details.append(element('summary','Starter code'),element('pre',starter));const b=element('button','Download starter');b.onclick=()=>download('week_'+m.week+'_starter.py',starter);section.append(details,b,element('p','Submit three added boundary tests, DESIGN.md, evidence and reflection. No final grade is automated.'));content.append(section)}status.textContent=content.children.length+' weekly modules shown.'}search.oninput=render;render()}).catch(e=>{status.textContent=e.message;content.append(element('p','Serve this preview over HTTP to load its curriculum.'))});

import {mkdirSync,copyFileSync,readFileSync} from 'node:fs';
const modules=JSON.parse(readFileSync('curriculum.json','utf8'));
if(modules.length!==16)throw Error('Expected 16 modules');
mkdirSync('dist',{recursive:true});
for(const file of ['index.html','portal.js','style.css','curriculum.json','syllabus.md','architecture.md'])copyFileSync(file,'dist/'+file);
console.log('Built static curriculum. No learner code executed.');

